  "page": 45,
  "content": "□관리 필요성\nㅇ 유사사고 수사결과 하천 점용허가를 받은 수허가자가 해당 현장을\n*\n( )\n중대시민재해 예방관리 현장에 미포함하여 안전‧보건확보 의무를\n미이행함을 주요 공소 사유로 언급\n* 오송 지하차도 침 수사고 관련 수사결과( 붙임1 ) 참조\nㅇ ( 법률자문 결과 공중이용시설의 관리상 결함으로 중대시민재해\n)\n발생시 점용자도 중대재해처벌법 상 관리책임 부담\n※ 법무법인(광장) 자문의견서\n‧ 귀 허\n사가 점용 설물 배 가를 통해 특정 시 을 타적으로 점유하고 관리업무를\n귀\n수행하고 있다면, 사의 경영책임자는 해당 시 설물\n에 대하여 중대재해\n처벌법 제9조에 따른 안전보건 확보의무를 부담하게 된다고 사료 됨\n.\n☞ 임시점용 공중이용시설에 대한 선제적 관리체계 구축 필요\nⅢ 관리계획\n관 리 방 향\n중대시민재해(공중이용시설) 관리 대상에 포함 관리\n□ 점용 관리주체별 역할\n구 분 관리주체 역 할 비고\n일 상 시설물 원 관리자 ‧ 시설물안전법상 정기점검 등 실시\n허\n( )\n시설물 원 관리자 ‧ 점용시설 훼손행위 단속 등\n가자\n( )\n점 용 점용공사 발주자 ‧‧ 점용허가조건 준수 여부 점검\n점용시설 훼손행위 단속 등\n*\n피허 가자\n점용공사 시공자 ‧ 점용허가조건 준수 시설훼손 금지 등 ( )\n설물\n* 점용시 천 관련법(하 허 법 등)과 점용 가조건(분기 1회)에 따른 안전관리에 한함",
