  "content": "□ 관리체계도\nC E O\n안전혁신처\n시설물별\n주관부서\n건 설 처 도 로 처 구조 물처\n점용기관 건 설사업단 개량 사업단, 지역본부, 지사\n대상시설 임시점용 공중이용시 설 (제방, 절토사면, 옹벽 등)\n□ 업무내용\n구 분 내 용 비고\n안전혁신처 ‧ 중처법 이행점검 실적 보고 → ( CEO) 상‧하반기\n‧ 시설물별 중처법 의무사항 이행 관리 총괄 ( )\n시설물별 ‧ 임시점용 공중이용시설 현황 관리\n주관부서 ‧ 시설물별 중처법 이행점검 결과 보고\n→안전혁신처\n상‧하반기\n( )\n‧ 시설물별 중처법 의무사항 이행 관리\n점용기관 ‧ 임시점용 공중이용시설 현황 관리․보고\n□ 중대시민재해 의무 이행사항 공중이용시설\nㅇ 관련 법령 중대재해처벌법 제 조 시행령 제\n: 9 , 10~11 조\n구 분 의무이행사항 비고\n① 필요한 인력의 확보\nⅠ 안전보건 ② 필요한 예산의 편성 및 집행\n관리체계\n.\n반기별\n구축 및 이행 ③ 안전점검 등을 계획하여 수행 보고\n④ 안전계획을 수립하게 하고 충실히 이행"
