  "content": "□ 과제별 세부 추진방안\n1 위험성평가 분석시스템 개발·도입\nAI\no 위험요인 자동 도출 과거 사고 사례 빅데이터와 당일 공종\n( )\n정보를 매칭하여 현장별 맞춤형 위험요인 및 대책 자동 추천\n지능형 점검항목 생성 가 도출한 위험요인을 기반으로 현\no ( ) AI\n장별 맞춤형 안전점검 체크리스트 자동 생성 및 제공\no 연동 및 전파 도출된 위험요인을 작업 전 근로자에게\n(T B M )\n즉시 전파 및 실질적인 안전점검 이행 확인\n☞ 주관적 경험에 의존하던 서류 중심 평가를 데이터 기반의\n객관적 예측 체계로 전환\n2 기반 안전업무 관리시스템 구축\nAI\no (B ig 시스템 구축 산업안전포털 內 사고발생 입력 정보\nD/\nB )\n및 기간 확대 및 안전관련 법령 기준 방침 등 현행화 , ,\no 데이터 기반 학습 사고발생 주요 위험요인에 대한 빅데이터\n( )\n분석으로 도출된 결과 를 바탕으로 데이터 기반 학습 *\nAI\n* A\nI가 사고발생 위험공종, 안전대책 등을 판 단할 수 있는 기준 마련\no 안전업무 실시간 활용 작업장별 당일 위험공종 자동표출 및\n( )\n실시간 대화형 서비스 제공을 통한 안전조치 및 사고 예방\nAI\n☞ 사고이력 및 최신 안전정보에 대한 빅데이터 분석결과를\n바탕으로 AI 학습을 통한 안전업무 실시간 활용\n* 세부내용 붙임자료 참조"
