  "title": "가시설물 안전관리 표준계획서(2차) 개정",
  "page": 92,
  "content": "1-10 가시설물 안전관리 표준계획서(2차) 개정\n안전혁신처-123\n(2026.01.19.)\n□ 개정 목적\nㅇ 표준계획서 월 개정 최신화 및 현장 개선의견 반영 (2022.12 )\nㅇ 가시설물 가설벤트 등 종 추가 ( , FCM ) 7\n* 작업단계별 근로자 역할, 이동동선, 행동요령 등 반영\nㅇ 중대재해 재발방지대책 자료집 반영 [’25.1]\n* 도로공사 중대재해 사고사 례 반영하여 기 존 10종 가시 설 안전수칙 개선\n□ 추진 경위\nㅇ ‘17. 12 가시설물 안전관리 표준계획서 최초 제정\nㅇ ‘22. 3 현장 개선의견 조회 건설사업단 ( )\nㅇ ‘22. 12 차 개정 및 배포\nㅇ ‘25. 9 차 개정 용역 발주 건설장비 표준 안전매뉴얼 제작 용역\n2 ( )\n□ 주요 개정 내용\n항목 개정 내용 비고\n1. 비 계 시방기준 내용 보완 등\n2. 시스템 동바리 거푸집 존 치기간 개정사항 보완 등\n3. 강재 거푸집 둥 거푸집기 (일반) 강재 해체방법 개선 등\n4. 강재 거푸집 둥 클 밍 슬립폼 설기 ( 라이 ) 치작업 추가\n5. 강재 거푸집 코핑 거푸집 코핑 강재 해체방법 개선 등\n6. 안전방망 -\n7. 방호선반 설 방호선반 치기준 내용 보완\n8. 슬래브 캔틸 버, 레 동바리 -\n9. 터 널 작업대차 널 설 터 작업대차 치기준 추가 등\n10. 라이 닝 거푸집 닝 거푸집 설 라이 치기준 추가 등\n□ 향후 계획\nㅇ 가시설물 안전관리 표준계획서 차 개정 및 배포 (2 ) (’26.11)\n* 개정본은 산업안전포탈(기준 및 매뉴얼 / 공사 내 기준 및 매뉴얼 / 공통) 등록",
