  "doc": "p1_11",
  "title": "고속도로 건설공사 안전점검 수행기관 지정기준 개정",
  "page": 93,
  "content": "1-11 고속도로 건설공사 안전점검 건설처-4542\n(2026.10.21.)\n공 통 수행기관 지정기준 개정\n□ 개 요\no 관련 법령 에 따른 건설공사 안전점검 수행기관 지정 및 세부기준\n*\n수립 의무 이행을 위해 자체기준을 수립 및 운용중에 있음 **\n* 건설기술진흥법 시행령 제100조의2, 건설공사 안전관리 업무수행지침\n** 건설처-4118[2020.9.16.], 건설처-5663[2020.12.17.]\n□ 문 제 점\no ( 기준 일괄적용 「건설공사 안전관리 업무수행 지침 국토교통부 」은\n) ( )\n초기점검을 정밀점검 수준으로 실시하도록 하는 등 점검 종류별\n요구 수준을 달리 정하고 있으나 현행 기준은 자체안전점검을 제외\n*\n,\n한 모든 점검에 대한 실적을 동일하게 인정하고 있어 점검 종류별\n난이도 및 조사범위에 대한 차이가 반영되지 않음\n* 초기점검 : 정밀안전점검 수준(제25조) / 공사재개 전 안전점검 : 정기안전점검 수준(제26조)\n[건설공사 안전관리 업무수행 지침(국토교통부)]\n제25조(초기점검의 실시) ① 시공자는 영 제98조제1항제1호에 따른 건설공사를 준공(임시사용을\n포함한다)하기 전에 문제점 발생부위 및 붕괴유발부재 또는 문제점 발생 가능성이 높은 부위 등의\n중점유지관리사항을 파악하고 향후 점검ㆍ진단시 구조물에 대한 안전성평가의 기준이 되는 초기치\n를 확보하기 위하여 「시설물의 안전점검 및 정밀안전진단 실시 등에 관한 지침」에 따른 정밀점검\n수준의 초기점검을 실시하여야 한다.\no 행정서류 과다 발주자가 발주청이 아닌 경우 기술인 실적 및\n( )\n*\n,\n유사용역 수행실적 인정을 받기 위한 증명서류 과다로 부담 초래\n-계약서 계약내역 세금계산서 최종보고서 발주자가 발급한 실적\n, , , ,\n증명서 사업자등록증 사본 등\n,\n* 발주자가 발주청인 경우, 발주청 발급(확인) 실적증명서만으로도 인정",
