  "content": "o ( 통합발주 근거 명시 점검 물량이 적은 경우 기관 단위 또는 둘\n) ,\n이상의 공구를 통합하여 지정공고 요청할 수 있도록 개정 제 조\n( 6 )\no 통합명부 활용 조달청에서 매년 작성‧검증‧관리하는 수행기관\n( )\n명부 활용으로 대체하여 수행기관 모집‧검증 등 행정절차 일원화\n-발주처 개별 모집공고 시행 관련 조문 삭제 제 조 등 ( 5 )\no ( 용어‧조문 현행화 법령 개정에 따른 명칭 및 인용조문 현행화\n)\n□ 향후계획\no 검토사항을 반영하여 고속도로 건설공사 안전점검 수행기관 지정\n‘\n기준 개정 및 배포\n’\n-개정일 이후 시행하는 지정공고부터 적용\n※ 붙임 : 1. 고속도로 건설공사 안전점검 수행기관 지정기준 개정 부 ( ) 1 .\n2. 신·구 조문 대비표 부 1 .\n3. 고속도로 건설공사 안전점검 수행기관 지정공고 안 부 ( ) 1 .\n4. 사업수행능력 평가신청서 작성지침 부 끝 1 . ."
