  "content": "1-13 작업중지 안내서 배포\n안전혁신처-2294\n(2025.09.01.)\n□ 배 경\nㅇ 작업중지권 행사 절차·기준·사례 등 이해하기 쉬운 안내서 제작\n으로 근로자 참여 유도 및 자기보호를 위한 안전문화 정착\n,\n□ 주요내용\nㅇ 개요 및 관련법령 산안법 공공기관 안전관리 지침 등\n: ,\nㅇ 활성화 대책\n신고 마일리지 제도 운영 우수근로자 포상 홍보·교육\n- ‘ ’ , ,\n-신속한 신고를 위한 모바일 앱 개발 안전신문고 월 ( - , ‘26.6 )\nㅇ 작업중지 절차\n-작업중지 요구 → 현장대피 → 현장조치 및 확인 → 작업재개\n*\n* 관리자 와 근로자간 분 쟁 발생시 협의체, 외부 전문기관 자문을 통해 해결\nㅇ 작업중지 요구 기준 급박한 위험 발생 우려 시 :\n고용노동부 도 공(19건)\n도급·발주 직영\n안전 난 설\n간 미 치 등 건 설 기계 구조검토 싸 카 진 인 후 중\n7건 미시행 등 8건 사고위험 등 11건\nㅇ 공종별 작업중지 예시 건설 폭염 등 건 유지 안전대 미착용 등 건\n: ( 8 ), ( 9 )\n□ 향후계획 : 전기관 배포 근로자 교육 시 활용 지속 업데이트\n, ( )",
