  "content": "3 이행확인 강화\n□ 혼재작업 조정 결과보고 및 이행 확인\n❶ ❷\n운 영 조정내용 반영 결과 보고 이행 확인점검\n절 차 각 시공업체 시공업체 → 조정자 조정자\n❶조정내용 반영 후 결과보고\nㅇ (보고대상) 해당 시공사 안전보건관리책임자 → 안전보건조정자\nㅇ (보고시기) 조정 내용 반영 조치 후 즉시 ( )\nㅇ (보고방법) 현장 여건에 맞춰 조정자와 협의된 보고 연락 체계 활용 ( )\nㅇ (보고내용) 조치완료 확인이 가능한 자료 사진대지 조정작업계획 등 [ , ]\n※ 조정자는 개선보고된 내용(자료)을 협의체 회의록과 함 께 보관\n❷이행 확인점검\nㅇ (점검주체) 안전보건조정자 ※ 필 요시 시공사 안전보건관리책임자 참여\nㅇ (점검내용) 조정결과 적정성 및 추가 혼재작업 위험요인 확인 ( )\n□ 조정자 업무 적정성 확인점검 실시\n구 분 점검주기 점검방법\n시행부서 반기 회 이상 1 기관 자체 안전점검시 포함 시행\n본 사 년 회 이상\n1 산하기관 점검시 포함 시행\nⅤ 행정사항\n□ (적용시기) 공문 시행 후 복합공종 조정협의체 회의부터 적용\n※ 적용대상 :  조정자 업무 개선 /  이행확인 강 화"
