  "content": "Ⅴ 개선방안\n□ 추진방향\n구분 현 행 (As - Is) 개 선 (To - Be)\n 계약문서 내 자료(일정) 제출 및  계약문서 내 기술지도 개선내용\n계약\n확인(평가)절차 등의 내용 미반영 추가 반영\n 기관별 기술지도요원의 역량,  지도요원 역량, 일정 공유 확인\n시행\n일정 및 결과확인 절차 상이 및 지도결과 확인절차 마련\n 사후평가 제도 도입\n완료  별도의 평가제도 없음\n* 지도기관의 전문성, 충실성 등 반영\n 계약단계\n□재해예방 기술지도 계약시 계약문서 內 개선내용 추가 반영\nㅇ (반영시기) 발주서류 작성시\n발주서류 작성 계약체결 의뢰 계약진행 계약체결 完\n공사시행부서 시행부서→계약부서 계약부서 도공 ↔ 지도기관\nㅇ (반영대상) 설계서 과업지시서 등\n( )\nㅇ (포함내용) 시행단계 공유·확인절차 및 완료단계 평가 실시 등\n※ 세부 계약문서 추가 반영내용은 [ 붙 임2] 참고",
