  "page": 143,
  "content": " 완료단계\n□ 재해예방 기술지도 사후평가 제도 도입\nㅇ (평가절차)\n등급 산정 후\n재해예방 사후평가 실시 평가결과 제출\n결과공유\n기술지도 종료 (종료후 14일 이내) (반기별)\n(다음해 1월말)\n해당기관 기관별(평가위원) 해당기관→본사 본사→全기관\nㅇ (평가시기) 재해예방 기술지도 완료 후 일 이내 14\nㅇ (대 상) 지도계약을 완료한 재해예방기술지도 전문기관 지도사 ( )\nㅇ (평가주관) 재해예방 기술지도 발주기관 본부 지사 ( , )\nㅇ (평가위원) 계약건별 명 3~4\n구 분 내 부 외 부\n평가위원 공사부서 담당 팀장 명 1\n도급업체 현장대리인 명\n감독원 명 1~2\nㅇ (평가방법) 평가표에 따라 위원별 평가 실시\n※ 평가항목 : 기 술지도의 전문성, 충 실도, 기여도 등\nㅇ (결과제출) 평가결과 취합 후 반기별 공문 제출 →안전혁신처 ( )\n※ 상반기 종료 계약건 : 7. 15까지, 하반기 종료 계약건 : 다음해 1. 15까지\nㅇ (평가결과) 지도기관별 평가점수 산술평균 5등급 (S~D) 산정\n등급 S A B C D\n점수 100~90 점 89점 점 ~80 79 점 점 점 점\n~70 69 ~60 60 점 미만\n·\n※ 해당연도 상 하반기 평가결과를 종 합\n하여 최종 등급 결정/통보(다음해 1월 말\n)"
