  "content": "ㅇ (결과활용) 추후 재해예방 기술지도 전문기관 선정시 참고\n- 현 행 건설재해예방전문지도기관 평가결과 고용노동부 주관 활용 ( )\n◈ 평가결과 확인방법 [산업안전보건공단 홈페이지(http://www.kosha.or.kr)]\n① 자주찾는메뉴 ☞ 민간재해예방기관 평가결과 ☞ 분야/지정관서 선택 후 확인 *\n* 분야 : 건설재해예방전문지도기관 / 지정관서 : 관할 지방노동관서 선택\n② 사업소개 ☞ 공공/민간기관 평가 ☞ 건설재해예방 전문지도기관 ☞ 자료실\n※ 2024년 건 설 재해예방 전문지도기관 평가결과(고용부/‘24. 9. 2 발표) 참고\n- 추 가 재해예방 기술지도 사후평가 결과도 함께 활용\nⅥ 행정사항\n□ (적용시기) 공문 시행 후 신규 지도계약 건부터 적용\n※ 단, 사후평가 제도 운 영은 ‘25년 계약건부터 시행\n□ (향후계획) 「산업안전보건법」시행령 개정시 기술지도 결과 보고서\n통보대상에 발주자 추가 반영 건의\n* (현행) 해당 사업장의 안전보건총괄책임자(실질적 총괄 관리자)에게만 통보\n붙 임 : 1. 재해예방 기술지도 제도 요약 ( )\n2. 계약문서 추가 반영내용 안 ( )\n3. 기술지도 결과보고서 양식 ( )\n4. 기술지도 개선지도 불이행 사항 통보서 양식 ( )\n5. 재해예방 기술지도 사후평가표 양식 ( )\n6. 년 건설재해예방 전문지도기관 평가결과 별도붙임\n’24 [ ]"
