  "content": "붙임 1 재해예방 기술지도 제도(요약)\n□ 법적근거\nㅇ「산업안전보건법」제 · 조 동법 시행령 제 조 별표 73 74 , 59~61 , 18~19\n□ 대상공사 공사금액 억원 이상 억 토목공사업 억 미만\n: 1 120 ( 150 )\n* (제외) 1개월 미만, 육지 미연결 섬지역, 전담 안전관리자 선임공사 등\n□ 계약주체 발주자·자기공사자: ( ’22. 8. 18 시행 )\n□ 계약시기 공사착공 전일까지:\n* 표준계약서(시행규칙별지104호) 사용, 체결일로부터 7일이내 시스템 입 력\n□ 지도기관 건설재해예방전문지도기관 또는 산업안전지도사\n:\n□ 지도분야 ① 건설공사 ② 전기·정보통신·소방시설공사\n: ,\n□ 지도횟수\nㅇ 기술지도 횟수 회 공사기간 일 일 ( ※ 소 버림\n) = ( ) / 15 단, 수점은\n例\n* ( = →소 버림\n) 공사기간 164일인 경우 : 164 / 15일 10.9회 수점 이하 에 따라 10회\nㅇ 공사시작 후 일 이내 회 실시 15 1\nㅇ 공사금액 억 이상인 경우 산업안전지도사 또는 기술사 등이 회\n40 8\n마다 번 이상 기술지도 실시\n* 8회마다 1회이상은 1 〜 8회, 9 〜16회, 17 〜24회 중 1 번 이상 방문 했 는지 여부로 판 단\n□ 기술지도 한계 및 지역\nㅇ 인당 일 최대 회 월 최대 회로 횟수 제한\n1 1 4 , 80\nㅇ 기술지도 지역은 해당 기관 지도사 이 지정을 받은 지역고용노동청의 ( )\n관할 지역으로 제한\n□ 기술지도 결과 관리\nㅇ 기술지도시 결과보고서를 작성 후 안전보건총괄책임자 등에게 제출\nㅇ 공사 종료시 기술지도 완료증명서 발급 →발주자 도급인 ( , )\n□ 서류의 보존 계약이 종료된 날로부터 년\n: 3"
