  "content": "Ⅳ. 개선 방안\n□ 개선방안 요약\n 평가절차 최초평가 → 정기점검 수시 재평가 추가\n( ) , ( )\n 평가항목 위험성평 삭제 → 위험작업 관리 계획 추가\n( ) ( ) ( )\n 공동계약 평가기준 대표사만 평가 → 공동구성원 전체 평가\n( )\n구 분 현 행 개 선\n평가절차 ․ 착공 전 최초평가 ․ (추가) 착공 후 정기점검 , 수시 재평가\n- (정기점검) 최초평가 재점검(분기별 합 동안전점검시)\n- (수시 재평가) 중대재해 발생시 등 신규 재평가\n평가항목 ․ 위험성평가 실시계획 ․삭 ( 제) 위험성평가 실시계획(△10∼20점)\n(10∼20점) ․ (신규) 위험작업 관리 계획(10∼20점)\n공동계약 ․ 대표사만 평가 ․ (공동이행) 공동작성된 서 류 평가(보수적)\n평가기준 (공동수급업체 제외) ․ (분담이행) 구성원별(면 허 각각 평가\n)\n․ (주계약자) 구성원별(공종) 각각 평가\n 산재예방조치능력평가 절차 개선\n목적 정기점검 등을 통한 안전보건 이행수준의 지속성 확보\nㅇ ( )\nㅇ 내용 착공 이후 정기점검 수시 재평가 기준 마련\n( ) ‘ ’, ‘ ’\nㅇ 세부기준( )\n구 분 정기점검 수시 재평가\n‧산재예방 조치능력평가 대상 ‧산재예방 조치능력평가 대상 전체\n시행대상\n* 제외대상 : 90일 미만 계약 건\n‧(분기별) 합 동안전보건점검시 ‧중대재해 발생 시\n시행시기 직\n‧조 ‧인력 등 관리체계 하향 변동시\n‧ 밖\n그 에 감독원 등이 필 판\n요 단시\n‧최초 평가내용 이행여부 점검 ‧해당시점 기준의 평가서 류 를\n시행방법 (관리체계, 운 영관리, 재해발생 수준) 신규로 제출 받 아 재평가\n‧점검일지에 점검결과 check",
