  "content": " 산재예방조치능력평가 항목 개선\n목적 중복서류 간소화 및 실효성 있는 안전보건능력 평가\nㅇ ( )\nㅇ 내용 위험성평가 삭제 → 위험작업 관리 계획 추가\n( ) ( ) ( )\n위험작업 대상 종류와 안전관리 계획 수립의 적정성을 확인\n-\n*\n* 도급사업 안전보건관리 매뉴얼 (고용노동부, 2021.12) 안전작업 허 가 항목 개선\nㅇ ( 변경현황 )\n구분 당 초 변 경\nA .\n1 침\n안전보건 경영방 및 목표 1 좌 동\n안전보건 2 안전인력 및 예산 2 좌 동\n관리체계\n3 종사자 의 견 3 좌 동\nB\n.\n4 위험성평가 실시규정 작성( 삭 제) 4 위험작업 관리 계획(신규)\n안전보건 5 개인보호구 지급계획 5 좌 동\n운 영관리\n… … … …\nC. 재해수준 10 산업재해 현황 수준 10 좌 동\n 공동계약 평가기준 마련\n목적 공동계약 종류별 평가기준 일관성 확보\nㅇ ( )\nㅇ 내용 계약의 이행책임 관계에 따라 평가 시행\n( )\nㅇ 평가기준 ( )\n구 분 서류제출 평가방법 비고\n‧대표사 가 제출 ‧공동 작성된 내용 으로 보수적\n공동이행 (공동수급체 내용 포함) 으로 평가 연대\n책임\n* 공동이행평가 별도 기준 마련\n분담이행 ‧ 구성원별 각각 제출 ‧구성원별 각각 평가 각자\n주계약자 ‧구성원 전체 기준만족시 착수 책임"
