  "content": "□ 정기점검\n점검대상 산재예방조치능력평가를 실시한 일 이상 계약 건\nㅇ ( ) 90\n- 일미만 계약 건 제외 합동안전·보건 점검 시행 주기 고려\n90 ( )\nㅇ 점검시기 분기별 일 기간 내 회 점검 원칙\n( ) (90 1 )\n-기 시행중인 합동안전·보건 점검시 산재예방 조치능력평가 정\n기점검을 병행하되 ,\n-계약기간·시점과 합동안전·보건 점검 시점 등을 고려하여 기관별\n탄력적으로 시행\n* (예시) 계약기간 90일 공사의 계약시점과 합동안전보건점검 시행시기가\n동일한 경우 준공시점에 정기점검 시기 도 래→ 공사 준공 전 별도 점검\nㅇ ( 점검방법 최초 평가서류 점검 후 합동안전·보건 점검일지\n) Check\n- 최초 평가내용 이행 지속여부 점검 관리체계 운영관리 재해발생 수준\n( , , )\n달\n* 기준미 시 보완 후 재평가\n※ 함동안전·보건 점검 일지 점검(예시) 붙 * [ 임2] 변경 양 식\n당 초 변 경\n점검결과 체크\n산재예방 조치능력 이행수준 유지여부 √"
