  "content": "붙임3 산재예방 조치능력 평가 항목(개선)\n□ 변경현황\n구분 당 초 변 경\nA.\n1 안전보건 경영방침 및 목표 수급인의 안전보건 경영 방침 및 목표\n[ ]\n안전보건 2 안전인력 및 예산 안전 전문인력 보유현황 안전 예산 현황\n[ ] ,\n관리체계 3 종사자 의견 종사자 의견 청취\n[ ]\n삭제 위험성평가\n[ ] 추가 위험작업 관리 계획 [ ]\n위험성 평가 실시규정 작성 위험 작업 대상별 관리 계획\n- -\n5 개인보호구 개인보호구 지급계획서\n[ ]\n안전점검 계획 점검항목 및 점검계획 수립\nB.\n안전보건 6 [ ]\n운영관리 7 교육실적 및 계획 안전보건 교육 및 계획\n[ ]\n8 신호 및 연락체계 도급‧수급업체간 연락체계\n[ ]\n9 비상대책 비상시 대피 및 피해 최소화 대책\n[ ]\n재해발생수준\nC.\n10 산업재해 현황 수준 최근 년간 산업재해 발생현황\n[ ] 3\n□ 세부내용\nㅇ 위험작업 관리 계획 점 (10 )\n구 분 우수 보통 미흡\n해당 사업의 위험작업 관리계획의 적정성 여부 10 6 3\n① 우수 우리공사 기준의 위험작업 대상여부를 정확히 인지하고 있고\n: ,\n이에대한 관리계획이 적정하게 작성되어 있음\n② 보통 위험작업 대상공사 혹은 관리계획 중 일부 내용이 누락\n:\n되거나 구체적이지 않음 또는 단순공종으로 해당사항 없음 . , .\n③ 미흡 위험작업 대상공사를 인지하지 못하며 관리계획도 작성\n:\n되어 있지 않거나 미흡함 ."
