  "page": 176,
  "content": "□ 위험작업별 세부 작업내용\n등 급 작업내용 분류 세부 공종 예시 해당여부\n- 교량받침 보수·보강 작업(교량점검시설 작업의 경우)\nH=10m이상 고소작업 교량\n- 바닥판 균열보수 (고소작업차 및 굴절식 점검차 이용)\n교량 - 교량하부 및 교각 균열·단면보수(비계 이용)\nH=2~10m 고소작업\n부대시설 - 톨게이트 지붕 도장보수\n각종 가시설 및 동바리, 비계 - 암파쇄 방호시설 설치시(가시설 항타 등)\n사면 √\nS 등의 설치, 해체 작업 - 계단식 옹벽 거푸집 설치\n기존구조물 파쇄 배수공 - 개거(U형 측구 등) 파쇄\n좁은 공간에서 다수 장비를\n포장 - 포장, 교면포장 등 각종 포장 보수작업\n이용하는 작업(레미콘, 백호, 덤프 등)\n- 임목벌채 작업\n임목 및 수목 등 제거 작업 사면\n- 비탈면 쇄석 제거\n- 고소작업차 및 굴절식 점검차를 이용한 교량점검\n- 교량 난간방호벽 개량시 하부 비계설치 및 해체 작업\n- 교량 투석방지망 설치 작업\n- 중앙분리대 분리부 추락 방지시설 설치\nH=10m이상 고소작업 교량\nA - 교량점검시설 설치 작업\n- 교량 배수관 설치 및 강교 재도장(외부)\n- 해안교량 전기방식시설 개량(배선 및 배관 설치공)\n- 기타 교량에서 시행하는 높이 10m이상의 고소작업\n대형 크레인을 이용한 작업 사면 - 절토비탈면 보수·보강(네일, 앵커 등)\n- A등급 세부 공종 중 작업 높이가 2~10m인 작업\n- 통과높이 제한시설 설치\n교량 √\n- 교대변위 보수보강\nH=2~10m 고소작업 - 기타 교량에서 시행하는 높이 2~10m의 고소작업\n- 터널 내오염 도장, 터널 라이닝 보수(균열 및 단면보수)\n터널\n- 터널등 교체작업\n암거 - 균열 및 단면보수\nB - 교면포장, 난간방호벽 개량, 신축이음설치,\n교량 √\n좁은 공간에서 다수 장비를 교량접속부 평탄성 개량 등\n이용하는 작업 터널 - 터널 공동구 개량 등\n(레미콘, 백호, 덤프 등) - 중분대 및 갓길측 교통안전시설 보수작업\n부대시설\n(방현망, 중앙분리대, 시선유도시설, 가드레일, 방음벽 교체 등)\n교량 - 교량점검시설 설치, 교량하부 가드휀스 설치 등\n소규모 크레인, 빔리프터 등을\n- 절토비탈면 보수ㆍ보강\n이용한 작업 사면\n(숏크리트, 콘크리트옹벽, 녹생토 등)\n밀폐공간 작업 교량 - 강교 재도장(내부) 등\n수중 작업 교량 - 해안교량 전기방식시설 개량, 수중점검 등\nC 점검로 설치 사면 - 절․성토부 점검로 설치, 해체 등\n교량, - 차선도색, 교량세척, 중분대 노면청소, 가로등\n이동식 차단작업 부대시설,\n기타 교체작업 갓길 삭초 작업 등"
