  "content": "Ⅲ 신호수·유도자 관리방안\n< 추 진 방 향 >\n안전관리비 적정 집행 및 중대재해 예방을 위한 신호수 관리 강화\n신호수 전문성 강화 주체별 역할 명확화 배치기준 및 정산\n① 신호수 전문성 강화방안\n□ 현장상주 안전보조원 운영방안 마련\nㅇ 신호수 전문성 연속성 숙련도 확보를 위해 공사규모에 따라\n, ,\n안전보조원 명 배치하여 전문신호수 통제원 역할 수행\n“ ” 3~4\n*\n“ ”, “ ”\n억\n* 2,200 억 액\n이하 : 3명, 2,200 초과 : 4명(최초 도급 기준)\n·원도급사에서 직접 고용하여 현장 상주 상용직\n고용주체 군필 술\n( )\n- 이공계 전문대학 학위 이상 ( , 경력자 또는 초급 기 자 우대)\n단, 채용이 어 려운 지역은 공업계고 졸\n업 이상 으로 변경 가능\n투입기간 ·안전관리계획서 승인 이후부터 최종 준공시까지 ( 최초 )\n률 % - 공정 투입 에 따라 15 이하인 경우 2명\n·“ 장비전담유도원 으로 우선 배치\n비 배 “ ” 투입\n”\n① 장 전담유도원을 치하는 경우 안전보조원 우선\n투입기준 - 특별한 사유 이 추가 신호수(일용 )를없 직 투입 하는 경우 정산 불\n가\n및 ② 위험등급별 관리기준에 따라 위험작업에 우선 치 (S 배 →A→B 順 등급 )\n주요역할 ※ 교통신호수는 비 순므 비\n교적 신호, 통제가 단 하 로 장 유도 업무가\n없 는 경우에만 투입 가능\n※ 원도급사 공사파 트 팀 소속( ) 진 안전관리담당자(건 법)를 보조\n· 非 작업기간 일 에 유해·위험 방지 및 점검업무 지원\n( )\n□ 신호수 안전관리 매뉴얼 배포\nㅇ 신호수 통제역량 강화를 위한 안전관리 매뉴얼 공유\n- 유해․위험요인과 안전조치 등 재해예방에 관한 사항\n- 기타 건설기계의 기계적 특성 및 안전·방호장치에 관한 사항\n□ 신호수 통제 권한 강화를 위한 캠페인 전개\nㅇ 매월 일 장비점검 시 안전관리책임자·안전보조원 합동점검 실시\nㅇ 신호수에 대한 인식개선을 위한 홍보물 인포그래픽 제작 ( )",
