  "page": 198,
  "content": "③ 배치기준 및 안전관리비 정산방안\n□ 신호수 배치기준\n신호수 유도자\n구 분\n교통신호수 장비전담유도원 (안전신호수)\n공용도로 공사용 진입 ·안전관리계획 수립 공종 ·안전관리계획 수립 외\n· (\n도로 접속부 )주요지점 모든 공종\n배치기준 ·양중기 작업 량물 취 및\n항타기, 항발기 작업\n(타워크레인, 중 급 포함)\n·하역운반기계, 건설기계 작업 접촉 려 (전도, 우 구간)\n정산방법 안전관리비 산업안전보건관리비\nㅇ “ 장비전담유도원 배치 대상 공종 첨#\n” [별 2 참조]\n·『건설기술진흥법』시행령 조의 안전관리계획 수립 공종 개 포장공\n·『건설기술진흥법』시행규칙 조의 가설구조물 안전성 검토 공종\n98 (8 ) +\nㅇ 그 외 공종은 유도자 배치 대상 공종\n“ ” [산업안전보건기준에 관한 규칙]\n· 양중기 작업 량물 취 및 항타기 항발기 작업\n(타워크레인, 중 급 포함)\n· 차량계 하역운반기계 건설기계 작업 접촉 려될\n,\n, (전도, 이 우 경우)\n□ 안전관리비 정산방안\n< 정 산 절 차 >\n① 안전관리계획서 ② 안전관리비 사용실적\n▶ ▶ ③ 안전관리비 정산\n수립 및 승인 보고 및 확인(반기)\n① 안전관리계획서 수립 및 적정성 검토 철저\n안전관리계획 수립 시 신호수 장비전담유도원 교통신호수 안전보조원\n배치계획을 포함 첨#\n- ( , ),\n[별 4 참조]\n※ 배\n안전관리계획서에 반영되지 않은 신호수 불 치작업은 정산 가\n비상상황 발생 시 즉시 운전원 근로자에게 위험을 전파할 수 있는\n스마트 경보체계 리모컨 경보등 무전기 등 를 안전관리계획에 포함\n- ,\n( , )\n□ 안전관리계획서 수립시 포함해야 할 내용 설 술진흥 (건 기 법 시행규칙 별표7)\n비\n① 신호수(교통신호수, 장 배 전담유도원), 현장상주 안전보조원 치계획\n비 - 트상 시 스마 디캠 경보체계 확보, 안전보조원 바 착용 등\n② 비집\n안전관리 행계획\n③ 안전교육계획(신호수 교육계획– 매 월 사각지대 체험교육 등)\n※ 배\n공사 중 감독지시서 등 배 소 치에 대한 감독행위( 치장 , 기간, 작업, 사유를 명시)에\n배\n따라 신호수를 추가 승\n치할 수 있으나, 안전관리계획서 수정 인 후 정산 가능"
