  "page": 199,
  "content": "② 안전관리비 집행실적․내역 확인 강화 현행 정기적 → 개선 매반기 ( : : )\n안전관리계획 이행 안전관리비 집행 실태 점검 매반기 첨#\n- , [별 3 참조]\n안전관리계획 및 안전관리비 집행내역 확인 중 지적사항 발생시\n( )\n-\n점검반 검토를 거쳐 부실벌점 환수 또는 현지시정 등 조치 ,\n※건 설 술진흥\n기 법 시행령 제87조(벌점 부과) 및 별표8(벌점관리기준)\n- 안전관리대책소홀 , 안전관리계획 보완 또는 미이행(건 설 사업자, 기 술 인)\n설\n- 시공자의 건 관리에 대한 확인 소홀 설 (건 사업관리, 기 술 인)\n※ 작업별 신호수 특별교육(산업안전보건법 시행규칙 별표5) 미이수시 과 료 부과 요청 태\n③ 안전관리비 교통신호수 장비전담유도원 는 기성 공정률 내에서 수량 정산\n( , )\n신호수 장비전담유도원 교통신호수 는 시간 단위 정산 기성공정률 내\n- “ ”\n안전보조원은 월 단위 정산 공정률 무관\n( , ) ( )\n- “ ”\n정부입찰․계약 집행기준 제 조에 따라 일용 상용근로자 보험료 정산\n( )\n- 94 ,\nⅢ 향후계획\n□ 안전관리비(신호수 인건비) 반영 노선 (동광주광산, 대산당진 및 향후 착공노선)\nㅇ 본 방침 적용 안전관리계획서 반영 안전보조원 배치 이행점검 등\n( , , )\nㅇ 대산 당진 동광주 광산 안전보조원 설계 반영 인력 투입\n설 설\n- , - , (~’24)\n※ 현장상주 안전보조원 계적용 검토(’22. 6, 계처-1914)\n신호수 인식개선을 위한 홍보물 인포그래픽 등 제작 대산 당진\n- ( ) ( - )\nㅇ 안전보조원 투입이 변경되는 시점 공정률 이전 에 운영효과 분석\n후 신호수 장비전담유도원 교통신호수 안전보조원 등 개선 수량 조정\n( 15% )\n( , ), ,\nㅇ 작업분류체계 에 따른 안전관리 매뉴얼 제작 검토 연구비또는건설사업비\n(WBS) ( )\n□ 미 반영 노선 (그 외 노선)\nㅇ 공사시행부서 검토 후 총사업비 조정 등 추진\n※ 도로건 설\n공사 안전관리 비 산정 가이 드 라인 제정(’24. 6, 국 토부)\n□ 현장상주 안전보조원 관리\nㅇ 현장상주 안전보조원 명칭 경력관리 우대 및 활용방안 검토 , ,"
