  "page": 204,
  "content": "□ 장비전담유도원 배치공종\n구 분 세부내용\n1. 높 브 켓 bra 비 비설 설․ ․\n이가 31미터 이상인 계 치 해체\n1의2.\n판 형 거푸집 높\n라 ( cket) 계 치 해체\n거푸집 설 ․\n2. 작업발 일체 또는 이가 5미터 이상인\n높 m ․거푸집 설벤트 설 ․\n및 동바리 치 해체\n※ 멘 량 피암 널 m\n및 동바리(가 포함) 치 해체\n이 5 이상\n높 판m 형․․암거 거푸집\n코핑 닝 거푸집설설․․\n라 교 , 터 5 미만 포함\n이 2 이상 및 동바리 치 해체\n널 支保工 높\n작업발 일체 교각, , 라이 치 해체\n흙막 설 ․\n3. 터 의 지보공( ) 또는 이가 2미터 이상인\n움직 설 물 설 ․\n이 지보공 치 해체\n․슬립폼 설 ․\n4. 동력을 이용하여 이는 가 구조 치 해체\n가설공사 ․F 두 설 F T 설 ․\n치 해체\n․ 설즈 설․\nCM 주 부 가시 , / 등 Set 치 해체\n①\n설물 ․․ 설트러 설 비 ·거푸집 설․ 설․\nILM 제작장, 가 노 , 가교각 등 Set 치 해체\n(시 안전성 검토 항목) MSS 이동식 가 계 등 Set 치 해체\n설\n(건 처-4813,‘19.10.18)\n높\nPSM 가 스 등 Set 치 해체\n판 설물 화 설\n4의2. 이 10미터 이상에서 외부작업을 하기 위하여\n공종별 작업발\n설 물 설 ․ 립ㆍ설 복합형\n및 안전시 을 일체 하여 치\n안전관리 하는 가 구조 치 해체\n계획서 설 물설 ․\n4의3. 공사현장에서 제작하여 조 치하는\n밖 ㆍ허 필\n가 구조 치 해체\n설 물설 ․\n5. 그 에 발주자 또는 인 가기관의 장이 요\n작성대상 ․․ 설 량비 높물막 설 낙․ 물\n하다고 인정하는 가 구조 치 해체\n(8개)\n가 교 , 가 이 치 해체\n설․\n․ 킹 널 설․ ․\n시스템 계( 이 무관), 하 방지 방호선반 치 해체\n․암\n․․ 량설쇄슬 벽브 설닥판설 거푸집\n․\n교각 워 타워, 터 작업대차 치 해체 이동\n벽 판 m 설 설․ ․\n파 방호시 치 해체\n교 라 (바 ) 및 동바리 치 해체\n가 방음 , 영구방음 (방음 7.0 이상) 치 해체\n② 굴착공사 물 m 설물 m 축\n및 발파공사 m 굴 널굴 ․\n폭발 을 사용하는 공사(20 이내 시 , 100 이내 사)\n10 이상 지하 착공사 / 터 착 발파공사\n③ 콘크리트공사\n④ 강구조물공사 굴 설물\n1, 2종 시\n설 량 벽널 모든 속\n(교 , 터 공종의 부 작업 포함)\n착기 타 작업(방호 , 공동구, 중분대 등)\n설물 비 옹벽 모든 속\n높옹벽\n2종 시 ( 탈면, 공종의 부 작업 포함)\n⑤ 토공사 합\n- 지면으로부터 노출된\n이 100미터 이상인\n- 지면으로부터 연 (\n이가 5미터 이상인 부분의\n직 鉛直 높\n) 이 30미터 이상을 포함한\n절토부로서 단일 수평연장 100미터 이상인 사면\n해체공사⑥\n층 축물 설\n건축설비공사\n⑦\n10 이상 건 신 , 해체공사\n타워크레인 공사 천\n⑧ 공기, 항타 및 항발기, 타워크레인 사용작업\n기타 기타 발주자가 인정\n하는 공사 속운 · 설·설물짐 비철거\n투입포장공사( 반 포\n인한 고 도로 시\n다 장\n해체(\n․ 량\n) 및 확장\n)공사 등\n개 으로\n배치공종 중 양중기 작업 (타워크레인, 중량물 취급 포함) 및 항타기, 항발기 작업 및 하역\n운반기계, 건설기계 작업(전도, 접촉 우려구간)"
