  "page": 212,
  "content": "붙임 4 안전관리계획서 신호수 배치 수량산정(안)\n□ 장비전담유도원 수량 산정 (일․인)\nㅇ “ 장비전담유도원 배치 대상 공종에 첨# 따라 배치일수 산정\n” [별 2]\n※ 예) 14,500일\n※ 안전관리계획서에 반영되지 않은 배 치작업(예 : etc.)은 정산 불가\n► 작업분 류 WB 체계( S)에 따라 세부 배 치작업 명기\n공종 대상시 설 위치 배 치기간 배\n치작업\na ․작업대차 설치 및 해체작업\n가설 OO 널\n공사 터 작업대차\nSt .00∼00\n000일 ․작업대차 자재운 양 반, 인\n(방향, 위치별)\n․작업대차 이동작업…\n굴 OO 널 _ 설 와 ․ 석거\n복없\n착 및 가 공사\n터 (부산) 2종 00일 부 제 작업\n발파공사 중 이 작성\n콘 트 OO 울 _ 설 와 ․ 량받침 양\n복없 ․철 양\n가 공사 교 인 작업\n크리 교(서 ) 1종 00일\n중 이 작성 근 인 작업\n□ 교통신호수 수량 산정 (일․인)\nㅇ 도로건설공사 안전관리비 산정 가이드라인에 따라 배치일수 산정\n\n   \n잔여 공사기간 ×    = 22( 일월 / ) x 78( 월 ) x\n\n    = 2,457\n\n일\n※ 공사용 진입 N\n도로 개수( )가 2개 일 때 산출예시임\n위치 배 치기간 배 치작업\na\nSt .00.000∼00.000 · 작업차 량 소\n통행안전, 통관리\n진입 # 도로 3\n000일\n· 관계자 외 출 입 통제\na ∼\nSt .00.000 00.000\n량\n현장 내 작업차 교차\n00일\n※ 실시 설 계시 산출된 배치일수를 초과하여 산정되는 경우 총사업 비 협의\n□ 일평균 투입인원 산정 (일․인/일)\nㅇ ( 장비전담유도원 교통신호수 잔여 공사기간 + ) /"
