  "content": "□ 현장상주 안전보조원 산정 (일․인, 22일/월 기준)\n공정률 까지 명 배치 잔여기간 동안 전체 공사비에 따라\nㅇ 15% 2 ,\n추가인원 배치\n- 22( 일월\n/ ) x 78( 월 ) x 2 명 + 22( 일월\n/ ) x 54( 월\n) x 명\n2 = 5,808 일\n※ 2,200 억 미만 : 3명, 2,200 억 초과 : 4명\nㅇ 수량조정계수에 따라 신호수 장비전담유도원 교통신호수 수량 조정 ( , )\n장비전담유도원  일   교통신호수  일   안전보조원  일 \n  \n장비전담유도원  일   교통신호수  일 \n□ 수량 산정\n① 당초 안전관리비 신호수 인건비 ≦ 변경 안전관리비 신호수 인건비\n( ) ( )\n※ 필 요시 총사업 비 협의 추 진\n② 전체 안전관리비 신호수 인건비 ( )\n장비전담유도원 교통신호수 안전보조원\n= + +\n③ 총사업비 협의 전까지 당초 안전관리비 내에서 안전관리계획서를\n작성할 경우 안전보조원 계상 후 잔여 사업비로 장비전담유도원\n,\n등 수량 산정 ※ 안전관리계획서 신호수 배치계획 검토 시 사업비와 함께 검토\n(공사관리팀 설계파트 협조 또는 검토)"
