  "page": 214,
  "content": "참 고 안전관리비(신호수 인건비) 정산 시 유의사항\n□ 유의사항\n[안전관리계획서, 공사일지(필요시 작업계획서), 정산서류 비교]\nㅇ 안전관리계획서 총괄안전관리계획 에 배치공종 대상시설 위치 배치 , , ,\n기간 배치작업 등 세부내용이 행선별 위치별 공종별 상세하게\n( )\n, , ,\n작성 되어있는지 확인하고 실제 신호수 배치와 일치 확인 ,\n특히 종 교량 터널 비탈면에 종속된 가설시설물은 가설공사로\n- , 1,2 , ,\n분류하여 작성 중복금지\n안전관리계획서 승인 전 안전관리비 정산 불가 단 소급정산 가능\n( )\n- ( , )\nㅇ 공사일지 필요시 작업계획서 로 신호수 배치작업 사실 확인 성명 등\n( ) ( )\nㅇ 감독원 지시에 따른 신호수 배치는 아래항목에 한하여 가능하나 ,\n안전관리계획서를 재승인 후 정산 가능 단 소급정산 가능 ( , )\n산업안전보건법에 따른 유도자\n-\n건설기술진흥법에 따른 장비전담유도원 교통신호수\n- ,\n[안전보조원, 장비전담유도원, 교통신호수 중복 확인]\nㅇ 특별한 사유 휴가 등 없이 안전보조원을 활용하지 않고 장비전담\n유도원 교통신호수를 투입한 경우 정산 불가\n( )\n,\nㅇ 안전보조원을 배치한 신호 장비전담유도 교통신호 작업은 안전보조원\n으로 정산 장비전담유도원 교통신호수로 중복 정산 불가\n( , )\n( , )\n[기타사항]\nㅇ 안전보건교육 정기 특별 와 같이 사업주가 부담해야 할 의무사항이\n포함되어 있는지 확인\n( , )\n- 신규 신호수 배치 전 특별교육 유해․위험작업 개 항목 실시여부 확인 ( 39 )\n․\n* 유해 위험작업 특별교육 대상은 작업계획서에 포함된 인원으로 산정(근로감독관 확인)\n※ 작업계획서 포함인원 : 관리감독자, 작업지 자, 신호수, 유도자, 근로자, 휘 운 필 전원( 요시)"
