  "page": 219,
  "content": "Ⅳ 신호수 안전관리 종합대책\n신호수 안전확보 및 유사사고 근절\n신호수 중심 장비(운전자) 중심 제도정비 및\n안전대책 안전대책 현장관리 강화\n사각지대 위험성 교육 교육 및 계도 캠페인 신호수 자격이수 도입\n신호수 안전지대 확보 장비 안전장치 점검 현장모니터링 강화\n시인성 향상 스마트 안전기술 활용 안전수칙 책임부여\n1. 신호수 중심 안전대책\n□ 장비 사각지대 위험성 교육 강화\n교육시기 신호수 신규 투입 및 분기별 회 이상 시행\nㅇ ( ) 1\nㅇ 교육내용\n( )\n체험교육 신호수 대상 장비 사각지대 체험교육 실시 월 회\n- ( ) ( 1 )\n영상교육 장비 운전자 시점의 장비 사각지대 위험성\n- ( )\n* 교육자료를 활용 장 비 접\n인 근무 범위(최 소 m\n5 이상 이 격) 교육\n신호수 사각지대 체험교육 사각지대 위험성 시청각자료(유 튜브 등 참고)",
