  "content": "별 첨 특별관리물질 취급시 필요사항\n□ 특별관리물질 현황\nㅇ 산업안전보건기준에 관한 규칙\n- 제 조 특별관리물질 취급시 적어야 하는 사항\n439 ( )\n- 제 조 특별관리물질의 고지\n440 ( )\nㅇ 산업안전보건기준에 관한 규칙 별표 [ 12]\n구분 유기화합물 금속류 산·알칼리류 가스상태 물질류\n종\n36 종 28 종 6 1종 종 1\n* 세부항목은 첨 부 참조\n□ 특별관리물질 취급시 조치 사항\n① 근로자에게 특별안전보건 교육 시간 이상 실시 16\n- 최초 작업 전 시간 이상 시간은 개월 이내 분할하여 실시\n4 , 12 3\n② 특별관리물질 취급일지 작성\n- (1) 물질명 사용량 및 재고량 취급일자 및 작업내용\n, , (2) ,\n(3) 취급상의 문제점 및 특이사항 발생시 처리 내역 등\n③ 특별관리물질의 고지\n- 게시판을 통해 근로자에게 알림\n④ 개인 보호구\n- 사업주는 호흡용 보호구 또는 피부 보호구를 지급하여 착용"
