  "content": "□ ( 본 사 안전보건예산 편성절차\n)\n예산지침 통보 → 예산(안) 협의 → 예산 확정 → 기관별 예산배정\n(9월) 익\n(10～11월) (12월) ( 년 1월)\n지침통보 기재부 지침에 따른 편성지침 작성 및 전기관 통보 기조실\nㅇ ( ) ( )\nㅇ 예산협의 예산요구 안 제출 및 협의 주관부서 및 각 기관 ↔ 기조실\n( ) ( ) ( )\n전담조직 참여 예산 안 에 대한 안전혁신처 협의‧검토 절차 추가\n- ( ) ( )\nㅇ 예산확정 기재부 협의 및 종합예산 안 이사회 심의·의결 기조실\n( ) ( ) ( )\nㅇ 예산배정 비용예산 운영계획 수립 및 예산 배정 기조실→각 기관\n( ) ( )\n□ ( 기관별 안전보건예산 집행절차\n)\n집행계획 수립 및 배정 → 예산사용 → 결 산\n(1월) (1월～12월) (12월～ 익년 1월)\n( 필\n요시 예산조정)\n계획수립 기존 예산집행지침 산업안전보건 예산 사용기준 및\nㅇ ( ) ,\n전년도 안전보건예산 실적 붙임 등을 참고하여 집행계획 수립 ( #2)\n계획수립 자료를 근거로 세세세목까지 예산 배정\n-\nㅇ 예산사용 안전보건예산 집행기준 붙임 에 근거하여 비용 집행\n( ) ( #3)\n※ 안전보건예산을 타 목적으로 유용 금 지\n예산조정 안전보건예산 감액 조정 시 임의조정 방지를 위하여\nㅇ ( ) ,\n안전보건관리책임자 기관장 승인을 득한 후 조정 ( )\n방 법 산업안전보건예산 조정승인서 붙임 문서 등록\n- ( ) ( #4),\nㅇ 결 산 당해 연도 집행실적 분석 및 차년도 계획 반영\n( )\n예산집행 완료 후 최초 집행계획 대비 실적 확인\n- ,\n차년도 계획 수립 시 미비점 개선 반영\n-"
