  "page": 262,
  "content": "붙임3 안전보건예산 집행기준\n구분 세부 내용\n∙ 근로자의 산업재해 및 건강장해 예방을 위한 목적으로 사용\n기본 원칙 ∙ 산업재해\n교통안전, 구조물안전 등 시민재해 예방을 목적으로 근로자\n예방과 무관한 비용 제외\n집\n(단, 산재예방 목적이 포함되어있는 경우, 안전보건예산으로 행 가능)\n①\n진비\n건강검\n∙산안법 제129조에 따른 근로자 일반 건강검진비\n사용항목\n(060201)\n② 진비\n특수건강검 ∙산안법 제130조에 따른 근로자 특수 건강검진비\n사용항목\n(060202) - 유해인자에 노출되는 업무에 종사하는 근로자\n의무실 운 비\n영 ∙의무실 운영비용\n③\n(060301)\n사용항목\n- 근로자 예방 접 비 품· 품 매\n종 용, 의약 보건용 구 등\n∙안전보건용품(소모성) 구입비용\n- 안전활동 관련 입 판 막배 간 비 , 현수 , 너 등 제작 용\n사용항목 - 안전관련 비품 모 걸 소화 액 설\n(안전 이대, 기, 자 치 등)\n④ 소모품\n안전보건\n-코 물품 진 키트 소\n로나19 관련 ( 칸막 단 , 독제, 마스크, 이 등)\n(120107)\n- 폭염대 비 물품 쿨 쿨 카프( 품 손난\n토시, 스 등), 방한용 ( 로 등)\n불\n가항목 ∙ 사무용 품 매\n및 가구 구 등\n∙안전보건 피복류 구입비용\n사용항목 ·\n- 동계 하계 안전 피복 피복류 지급기준에 의한\n⑤ 피복비\n안전보건\n-그 밖 입\n에 별도로 구 피복류\n하는 안전보건 목적의\n(130701)\n불\n가항목 ∙ 안전보건 목적이 없 피복 입비 는복 복 구 (일반 근무 , 체육 )\n∙ 본사, 본부, 지사, 영업 소 건물과 구축물, 설비, 전기 등\n등 의 유지관리 시 산업재해 예방을 위한비 용\n- 안전시 설설 ‧ ‧ 비 치 해체 보수 용\n사용항목 난 락\n(안전 간, 추 설\n방호망, 방호장치, 안전표지, 유도시 등)\n⑥\n안전보건\n수선유지 비 -밀폐 물품 매비\n공간 작업 구 용\n(172301)\n소농 측\n(산 도 흡 송풍\n정기, 호 기, 기 등)\n∙ 안전관련 정보시스템 구 축․운 비 영 및 유지보수 용\n불\n가항목 ∙ 산업안전과 관련 없 설 비 는 일반적인 시 보수 용"
