  "content": "구분 세부 내용\n∙산업안전보건관련 용역 비용\n- R&D 설\n개발용역, 안전점검 대행 용역, 시 개선 용역 등\n⑦\n안전보건\n수수료\n사용항목\n※ 택\n용역 과업내용에 따라 안전보건수수료, 안전보건자문료 일\n(200115) ∙작업환경측정 수수료\n불\n가항목 ∙ 옥 설 콜센\n외부회계감사, 사 시 비\n관리, 터 등 용역사업\n∙산업안전보건 관련 자문·평가·심사·기술지도 등의 비용\n사용항목\n택\n⑧\n안전보건 ※ 용역 과업내용에 따라 안전보건수수료, 안전보건자문료 일\n자문료\n(200205)\n불\n가항목 ∙안전인력 채용 관련 비 용(인사업무)\n⑨ 안전‧보건관리 사용항목 ∙안전관리, 보건관리업무 대행수수료\n업무대행수수료\n⑩ (200302)\n(200303) 불\n가항목 ∙ 소 방, 전기, 가스 등에 관한 안전관리업무 대행 수수료\n∙산안법 제93조에 따른 안전검사 비용\n⑪\n안전검사\n수수료\n사용항목\n프트 압\n- 크레인(2t 이상), 리 곤돌 소\n, 력용기, 라, 고 작업대 등\n(200409)\n불\n가항목 ∙승 강기 점검, 수질검사, 가스 안전검사 등\n∙산업안전보건관련 교육 수강료, 참가비\n훈 비\n안전보건 ∙안전보건 교육 및 워크숍 준비 비용(물품구매, 다과 등)\n⑫\n교육 련\n(251001) 사용항목 ∙안전체험관 구축·운영 비용 등\n(251002)\n≀ (251003) ※ 산안법에 따른 법정교육 : 251001～251007\n⑲ (251004)\n(251005)\n※ 기타 안전보건을 위한 자체방 침 교육 : 251101\n긴 밀 진 소\n(251006)\n불\n(251007) ∙교통안전( 급자동차), 정 안전 단, 방안전 관련 교육\n(251101) 가항목\n∙교육과 관련하여 실시하는 간담회 비 용\n사용항목 ∙유해위험요인 제보, 제도개선, 안전활동우수자 등 포상비용\n⑳ 비\n안전보건\n포상\n(270604)\n불\n가항목 ∙산업안전보건 활동과 관련 없 는 포상 비 용\n사용항목 ∙안전관련 행사(안전기원행사, 안전점검의 날 등)\n◯\n안전보건\n행사 비\n(350107)\n불\n가항목 ∙안전관련 행사 후 실시하는 간담회 비용 등"
