  "title": "산업재해 재발방지대책 수립·이행 유의사항",
  "page": 268,
  "content": "1-28 산업재해 재발방지대책 수립 안전혁신처-2237\n(2022.08.18.)\n공 통 이행 유의사항 알림\n□ 목 적\no 가상수사를 통해 도출된 재발방지대책 수립 및 이행시 미비점을\n개선하여 중대재해처벌법 의무사항의 충실한 이행 도모\n,\n□ 실시근거\no 산업안전보건법 제 조 산업재해 발생 은폐 금지 및 보고 등\n57 ( )\no 중대재해처벌법 제 조 제 항 제 조 4 1 2\no 우리공사 안전보건관리규정 제 조 사고원인 조사 및 대책 수립 63 ( )\no 「 매뉴얼」산업재해조사 활동 지침\nKOSHA-MS 전환 (ISO 45001 )\n□ 관련 미흡사항 (중처법 가상수사 결과, ‘22. 6)\no ( 수 립 사고예방 목적 달성을 위한 구체적인 대책 제시 미흡\n)\no ( 이 행 작업계획서나 안전교육 등에 재발방지대책 미반영\n)\n□ 재발방지대책 수립·이행\no 절 차\n① 사고조사 → ②수립\n재발방지대책 → ③ 종합대책 수립 → ④ 재발방지대책\n및 보고 및 전파 이행\n【시행부서 】 【 시행부서 】 【 주관부서, 안전혁신처 】 【 산하기관 】\no 대 상 중대재해 산안법 중대산업재해 중처법 재해 중처법 제 조\n: ( ), ( ), ( 4 )\n※( 붙 # 임 1) 재발방지대책 수 립범 위 및 이행방안 검토[안전혁신처-142(22.01.18)]\no 수립내용 사고 개요 재해정보 등 공사현황 현장조사 내용\n: ( ), , ,\n사고원인 재발방지대책 재해상황도 등 포함\n, ,",
