  "title": "붙임#1 재해 발생시 재발방지대책 수립 범위 및 이행절차",
  "page": 273,
  "content": "붙임#1 재해 발생시 재발방지대책 수립 범위 및 이행절차\n구 분 내 용\n∘산업재해 중\n- 사망자 1명 이상\n중대재해\n대상\n- 3개월 이상 요 양 필 이 요한 부상자 동시 2명 이상\n(산업안전\n- 부상자 또는 직 병\n업성 질 자 동시 10명 이상\n보건법)\n재발방지대책 보고\n→\n근본대책수 립 및 통보\n→ 합 립\n종 대책수 및 전파\n절차 (→사장/주관부서) (→안전혁신처) → ( 전기관)\n【 시행부서 】 【 주관부서 】 【 】\n안전혁신처\n∘산안법 상 산업재해 중\n중대산업\n재 해\n- 사망자 1명 이상\n대상\n- 동일사고로 6개월 이상 치료 부상자 2명 이상\n(중대재해\n- 동일유해요인으로 직 업성 질 병 자 1년내 3명 이상\n와\n처벌법)\n절차 ∘중대재해 이상의 재해로 중대재해 동일하게 관리\n∘1개월 이상 치료가 필 요한 부상이 1년 이내에 2 번 이상 반 복*\n발생하는 경우 또는 3개월 이상 치료가 필\n요한 부상자 1명\n이상 발생시\n대상\n* 반 복 : 동일인 or 동일장 소 or 동일유해요인 및 원인 or 동일유 형\n** 시행부서에서는 1개월 이상 치료가 필 요한 부상 발생시 주관부서\n및 안전혁신처 보고\n① 개별 사업장에서 2회이상 반 복 하여 발생한 산업재해\n재 해 대책수 립 및 보고 → 검토 및 통보 →\n전파\n(→전 기관)\n(중대재해\n【 시행부서 】 【 주관부서 】 【 안전혁신처 】\n처벌법\n제4조\n①항2)\n② 우리공사 전체 사업장에서 반 복 발생한 산업재해\n절차 대책수 립 및 보고 → 검토(경유) →\n종 합 대책수 립 및 전파\n(→전 기관)\n【 시행부서 】 【 주관부서 】 【안전혁신처 】\n③ 3개월 이상 치료가 필 요한 부상자 1명이상 발생시\n대책수 립 및 보고 → 검토 및 통보 →\n전파\n(→전 기관)\n【 시행부서 】 【 주관부서 】 【 안전혁신처 】"
