  "page": 274,
  "content": "붙임#2 재해요인 원인분석 예시\n구분 재해요인\n◈떨 짐 어 재해\n- 이동식 사다리의 변 형 끄럼 및 미 방지조치\n-고소 작업용 발 판 태의 강도 및 고정상\n-고소 작업장 소 난 설 태\n의 안전 간 치상\n- 개구부/ 맨홀 덮 등의 개 등\n- 안전대 걸 설설 태 이시 치 상 , 작업동선 적정성\n◈끼 임 재해\n-프 압\n레스/ 력용기 등 위험기계 기구 방호장치 · 설치/기능유지\n물 - 회전기계의 동력전 달 덮 설부 방호 개 치\n적요인\n-리 프트 승 / 강기 등 운 설비반 울 입 의 방호 /출 문 방호조치\n- 공작기계/목공기계 등의 방호조치 등\n◈넘 짐 어 재해\n- 작업장 바 닥 물 름\n의 /기소 태 등의 청 상\n- 작업장 내 제 품 돈 태\n/자재 등의 정리정 상\n- 작업장 내 근로자/ 운 설비 반 등의 통로확보 등\n◈ 기타 재해\n- 충전부 절연조치 및 덮 설 태\n개 치상\n- 전기기계 기구의 · 접지 등\n·\n- 안전수칙 작업절차 준수 여부\n인적요인 - 작업 중 무리한 동작 및 불필 요한 행위\n-근 골격 계질환 부담작업의 작업방법\n- 근로자 정기/특별 안전보건교육 실시\n관리적요인 - 작업장 안전점검 실시상 태\n- 안전검사 대상 기계 기구의 안전검사 실시 상 · 태 등"
