  "page": 295,
  "content": "1-30 안전·보건 관계법령에 따른 안전혁신처-1081\n(2022.04.29.)\n공 통 의무이행 점검방안\n□ 추진개요\nㅇ 중대재해처벌법 시행령 제 조 제 항 제 호에 의거한 안전·보건 5 2 1\n관계법령에 따른 의무이행 점검항목을 정하고 이에 따라 점검을\n시행하고자 함\n◈ 시행령 제5조 제2항 제1호\n안전 ㆍ 보건 관계 법령에 따른 의무를 이행 했 는지를 반기 1회 이상 점검하고,\n직접 점검하지 않은 경우에는 점검이 끝난 후 지체 없 이 점검 결과를 보고 받을 것\n□ 점검방안\n시 기 총 회 상‧하반기 각 회\nㅇ ( ) 2 ( 1 )\nㅇ 내 용 산업안전보건법 의무 이행사항 점검 붙임\n( ) ( #1)\n- 점검항목 사업주 건 도급인 건 발주자 건\n: 50 , 10 , 10\nㅇ ( 대 상 실질적으로 지배‧운영‧관리하는 사업 또는 사업장\n)\n- 직영 및 중처법 대상 도급·용역·위탁 등\nㅇ ( 방 법 위탁용역 시행 본사 안전혁신처 직할 및 산하기관 각 기관별\n) ( : / : )\n- 위탁 수행기관 안전·보건 관계 법령에 따라 중앙행정기관의 장이 지정한 기관\n:\n☞ 안전관리전문기관 보건관리전문기관 안전보건진단기관 건설재해예방전문지도기관등\n, , ,\n* 안전보건관리책임자 등의 업무수행 평가 포함 안전혁신처 호 ( -197 (2022.01.21.))\n□ 행정사항\nㅇ 「안전 준법경영 절차서」에 따라 반기별 위탁점검 결과 보고\nㅇ 미이행 사항에 대해 즉시 조치 시행 안전보건관리 총괄 책임자 주도 ( ( ) )\n- 조치시 인력·예산이 수반되는 경우 본사 주관부서 등과 협의 및 조치",
