  "title": "Ⅱ 점검자 안전 행동요령",
  "page": 303,
  "content": "1-31 건설 및 유지관리현장 안전혁신처-1076\n(2022.04.29.)\n공 통 점검자 안전 행동요령\nⅠ 추진배경\n□ 그 동안 공사장 안전관리는 직접 작업을 시행하는 근로자에 맞추어\n관리하였으나 건설․유지관리현장 점검자에 대한 안전수칙 부재\n□ 점검자가 준수해야 할 안전관리에 관한 사항을 정함으로써\n점검시 발생할 수 있는 재해를 예방코자 함\nⅡ 점검자 안전 행동요령\n‣ (적용대상 본사 산하기관 지역본부 지사 건설사업단 등 및\n) , ( , , )\n직할기관 점검업무 관련 직원 등\n‣ 적용현장 건설사업단 공사 현장 직영･도급 작업장 등\n( ) ,\n 현장 위험요인\n① 점검 중점검대차 고소작업차 떨어짐, 맞음 및 에서\n떨 짐 어 ② 점검장비 기기 맞음 및 에 의한 사고\n맞 음 ③ 고소작업 장소 안전난간 개구부 떨어짐\n의 및\n④ 설물 난\n시 떨어짐 방지시설의 파손\n의 간 등\n넘 짐 어 ① 시야 확보가 어려운 어두운 장소 신체 넘어짐 점검시 및\n부딪힘 부딪힘\n① 통행차량 에 의한 사고\n교통사고 ② 점검차량 현장 이동 시 교통사고\n③ 점검자의 도로 횡단 시 사고\n① 주위고압선 접촉 감전 에 의한\n감전사고\n② 설물시 기계‧전기시설물 작동 중 감전\n점검 시",
