  "title": "Ⅱ. 작업지휘자 배치기준",
  "page": 331,
  "content": "1-34 작업지휘자 및 신호수 배치기준 검토\n안전혁신처-2275\n(2021.09.06.)\nⅠ. 추진배경\n□ 최근 작업장내 작업지휘자와 신호수 미배치로 인한 중대재해\n가 지속 발생함에 따라\n*\n,\n＊(‘20.6) 이동식 크레인 붐길 이 조정 중 근로자 깔림 휘 , 작업지 자 미 배 치\n(‘21.4) 아스 팔트 포장작업 중 후 진 하는 덤프트럭 깔림 에 , 신호수 미 배 치\n□ 관련법에 따른 배치기준을 명확히 하여 작업장 안전관리 내실\n화를 도모하고자 함 .\nⅡ. 작업지휘자 배치기준\n【관련근거】\n◆ 산업안전보건기준에 관한 규칙 제 조 사전조사 및 작업계획서의 38 (\n작성 등 조 작업지휘자의 지정 조 수리 등의 작업 시 조치\n), 39 ( ), 206 ( )\n□ 작업지휘자 역할\nㅇ 작업계획서에 수립된 내용에 따라 작업을 지휘하는 업무 전담\n□ 배치기준 붙임 작업예시 [ #1 ]\n① 차량계 하역운반기계 등을 사용하는 작업\n＊ 화물 자동차를 사용하는 도로상의 주행작업 및 근로자가 없 충돌\n어 위험이\n없 는 경우는 제외\n② 굴착면의 높이가 이상이 되는 지반의 굴착작업 2m\n③ 교량의 설치·해체 또는 변경 작업\n＊ 상부구조가 금속 또는 콘 트\n크리 구성, 높 m 이 5 이상이 거 나 교 량 의 최대 지간\n길 이가 30 m이상인 교 량 으로 한정",
